package com.pixel.pokecollect.data

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import pokecollect.shared.generated.resources.Res

/**
 * Loads the bundled species list (generated by scripts/build_dataset.py) into Room.
 *
 * Runs on every launch but only writes when the bundled version differs from the stored one,
 * so a new dataset (e.g. Gen 10) ships as a resource swap, not a schema migration.
 */
class DatasetSeeder(private val dao: PokemonDao) {

    suspend fun seedIfNeeded() {
        val dataset = json.decodeFromString<BundledDataset>(Res.readBytes(DATASET_PATH).decodeToString())
        if (dao.datasetVersion() == dataset.version) return
        dao.replaceDataset(dataset.version, dataset.pokemon.map { it.toEntity() })
    }

    private companion object {
        const val DATASET_PATH = "files/pokemon.json"
        val json = Json { ignoreUnknownKeys = true }
    }
}

@Serializable
private class BundledDataset(
    val version: String,
    val pokemon: List<BundledSpecies>,
)

@Serializable
private class BundledSpecies(
    val id: Int,
    val name: String,
    val slug: String,
    val generation: Int,
    val types: List<String>,
    val imageUrl: String,
) {
    fun toEntity() = PokemonEntity(
        id = id,
        name = name,
        slug = slug,
        generation = generation,
        type1 = types.first(),
        type2 = types.getOrNull(1),
        imageUrl = imageUrl,
    )
}
